namespace CSharpPracticum.Tasks.Level2;
internal class Temperature{private double celsius;public double Celsius{get=>celsius;set{if(value< -273.15)throw new ArgumentOutOfRangeException(nameof(value));celsius=value;}}public double Fahrenheit=>Celsius*9/5+32;}
internal class Task32_Temperature:ITask{public string Title=>"Задание 32: Свойства с валидацией (Temperature)";public string Description=>"Проверять температуру Celsius при присваивании и вычислять Fahrenheit.";public string[] Requirements=>new[]{"Celsius не ниже −273.15.","Некорректное значение вызывает ArgumentOutOfRangeException.","Fahrenheit только для чтения.","Показать корректное и некорректное присваивание."};public void Run(){Temperature t=new(){Celsius=25};Console.WriteLine($"{t.Celsius}°C = {t.Fahrenheit}°F");try{t.Celsius=-300;}catch(ArgumentOutOfRangeException e){Console.WriteLine(e.Message);}}}
